import{_ as a,o as i,c as t,ag as s}from"./chunks/framework.D9ghT4bC.js";const g=JSON.parse('{"title":"Creating a custom tileset","description":"","frontmatter":{},"headers":[],"relativePath":"Modders/Creating-a-custom-tileset.md","filePath":"Modders/Creating-a-custom-tileset.md"}'),l={name:"Modders/Creating-a-custom-tileset.md"};function n(o,e,r,h,d,p){return i(),t("div",null,[...e[0]||(e[0]=[s(`<h1 id="creating-a-custom-tileset" tabindex="-1">Creating a custom tileset <a class="header-anchor" href="#creating-a-custom-tileset" aria-label="Permalink to &quot;Creating a custom tileset&quot;">​</a></h1><p><strong>You should read the <a href="./Mods.html">Mods</a> page first before proceeding</strong></p><p>In order to add a tileset mod (yes, tilesets are just another type of mod), all you need to do is add your images under Images/Tilesets/MyCoolTilesetExample and enable the mod as a permanent visual mod - the game will recognize the tileset, and allow you to pick it in the options menu.</p><p>Let&#39;s look at the example &quot;Grassland+Jungle+Dyes+Trading post&quot; to learn how the game decides which images it should use for this tile:</p><ol><li>When there is a rule variant entry in the <a href="#tileset-config">tileset config</a> for this tile we will use the entry.</li><li>Else if there is an image called &quot;Grassland+Jungle+Dyes+Trading post&quot; we will use it instead.</li><li>Otherwise, we will check if there is an image called &quot;Grassland+Jungle&quot; (BaseTerrain+Terrainfeatures) and &quot;Dyes+Trading post&quot; (Resource+Improvement) and use the remainings of it. Let&#39;s say you made an image called &quot;Grassland+Jungle&quot; but none called &quot;Dyes+Trading post&quot;. In the end, we will then use the images &quot;Grassland+Jungle&quot;, &quot;Dyes&quot; and &quot;Trading post&quot;.</li></ol><p>All these images can also use era-dependant variants if you want to change the appearance of, let&#39;s say, &quot;Trading post&quot; throughout the game. Just create images and add the suffix &quot;-[era name]&quot;. E.g. &quot;Trading post-Classical era&quot;, &quot;Trading post-Industrial era&quot;, etc.</p><p>It is advised to use the layered approach (1 and 3) often because it comes with a few advantages. Mainly:</p><ul><li>Decreased filesize (on disk, for downloads)</li><li>Easier support for new terrains, improvements, resources, and for changing existing tiles</li></ul><p>You should keep in mind that the default rendering order is: BaseTerrain, TerrainFeatures, Resource, Improvement.</p><h2 id="tileset-config" tabindex="-1">Tileset config <a class="header-anchor" href="#tileset-config" aria-label="Permalink to &quot;Tileset config&quot;">​</a></h2><p>This is where tileset configs shine. You can use these to alter the way Unicv renders tiles.</p><p>To create a config for your tileset you just need to create a new .json file under jsons/Tilesets/. Just create a .txt file and rename it to MyCoolTilesetExample.json. You only have to add things if you want to change them. Else the default values will be used.</p><p>This is an example of such a config file that will be explain below:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;useColorAsBaseTerrain&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;false&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;useSummaryImages&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;true&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;unexploredTileColor&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;r&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;g&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;fogOfWarColor&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;r&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;g&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;b&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">&quot;a&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">},</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;fallbackTileSet&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">null</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;tileScale&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0.9</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;tileScales&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;City center&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;Citadel&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1.5</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;ruleVariants&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;Grassland+Forest&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Grassland&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ForestForGrassland&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">        &quot;Grassland+Jungle+Dyes+Trading post&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Grassland&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;JungleForGrasslandBack&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Dyes+Trading post&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;JungleForGrasslandFront&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h3 id="usecolorasbaseterrain" tabindex="-1">useColorAsBaseTerrain <a class="header-anchor" href="#usecolorasbaseterrain" aria-label="Permalink to &quot;useColorAsBaseTerrain&quot;">​</a></h3><p>A boolean value (&quot;true&quot; or &quot;false&quot;). Default value: &quot;false&quot;</p><p>If true, an additional &quot;Hexagon&quot; image is placed below each tile and colored in the corresponding BaseTerrain color. This removes the necessity to add individual BaseTerrain images. This is how the &quot;Minimal&quot; tileset works.</p><h3 id="usesummaryimages" tabindex="-1">useSummaryImages <a class="header-anchor" href="#usesummaryimages" aria-label="Permalink to &quot;useSummaryImages&quot;">​</a></h3><p>A boolean value (&quot;true&quot; or &quot;false&quot;). Default value: &quot;false&quot;</p><p>If true, summary images are used for specific groups of images instead of using individual tile images. The summary images must be placed in the same folder as every other tile image. Summary images used:</p><table tabindex="0"><thead><tr><th>Image group</th><th>Summary image</th></tr></thead><tbody><tr><td>Natural wonders</td><td>&quot;NaturalWonder&quot;</td></tr></tbody></table><h3 id="unexploredtilecolor" tabindex="-1">unexploredTileColor <a class="header-anchor" href="#unexploredtilecolor" aria-label="Permalink to &quot;unexploredTileColor&quot;">​</a></h3><p>A color defined with normalized RGBA values. Default value: &quot;{&quot;r&quot;:0.24705882, &quot;g&quot;:0.24705882, &quot;b&quot;:0.24705882, &quot;a&quot;:1}&quot; (DarkGray)</p><p>Defines the color of the unexplored tiles.</p><h3 id="fogofwarcolor" tabindex="-1">fogOfWarColor <a class="header-anchor" href="#fogofwarcolor" aria-label="Permalink to &quot;fogOfWarColor&quot;">​</a></h3><p>A color defined with normalized RGBA values. Default value: &quot;{&quot;r&quot;:0, &quot;g&quot;:0, &quot;b&quot;:0, &quot;a&quot;:1}&quot; (Black)</p><p>Defines the color of the fog of war. The color gets approximated by 60% to allow the colors of the images below to shine through.</p><h3 id="fallbacktileset" tabindex="-1">fallbackTileSet <a class="header-anchor" href="#fallbacktileset" aria-label="Permalink to &quot;fallbackTileSet&quot;">​</a></h3><p>A string value. Default value: &quot;FantasyHex&quot;</p><p>The name of another tileset whose images should be used if this tileset is missing images. Can be set to null to disable the the fallback tileset</p><h3 id="tilescale" tabindex="-1">tileScale <a class="header-anchor" href="#tilescale" aria-label="Permalink to &quot;tileScale&quot;">​</a></h3><p>A float value. Default value: 1.0</p><p>The scale of all tiles. Can be used to increase or decrease the size of every tile. Is being used by the tileset mod <a href="https://github.com/ravignir/5Hex-Tileset" target="_blank" rel="noreferrer">5Hex (made by ravignir)</a> to fake shadows.</p><h3 id="tilescales" tabindex="-1">tileScales <a class="header-anchor" href="#tilescales" aria-label="Permalink to &quot;tileScales&quot;">​</a></h3><p>A dictionary mapping string to a float value. Default value: empty</p><p>Used by the &quot;Minimal&quot; tileset to scale all its tiles except the base terrain down. Each entry overrides the tileScale value for the specified tile.</p><h3 id="rulevariants" tabindex="-1">ruleVariants <a class="header-anchor" href="#rulevariants" aria-label="Permalink to &quot;ruleVariants&quot;">​</a></h3><p>A dictionary mapping string to a list of strings. Default value: empty</p><p>The ruleVariants are the most powerful part of the tileset config. With this, you can define, for a specific tile, which images and in which order these images should be used.</p><p>An example is given in the code above. For the tile &quot;Grassland+Jungle+Dyes+Trading post&quot; we then use the images &quot;Grassland&quot;, &quot;JungleForGrasslandBack&quot;, &quot;Dyes+Trading post&quot; and &quot;JungleForGrasslandFront&quot; in that order.</p><h2 id="fog-and-unexplored-tiles" tabindex="-1">Fog and unexplored tiles <a class="header-anchor" href="#fog-and-unexplored-tiles" aria-label="Permalink to &quot;Fog and unexplored tiles&quot;">​</a></h2><p>Unciv distinguishes between &quot;unexplored&quot; tiles, which are tiles the Civ has never seen, and &quot;not visible&quot; tiles, which are those that were seen once but now are not.</p><p>Not visible tiles are grayed out by design, and on top of that have the <code>CrosshatchHexagon.png</code> image applied to them.</p><p>Unexplored tiles display the <code>UnexploredTile.png</code> image, on top of which <code>CrosshatchHexagon.png</code> is applied.</p><p>You can set the CrosshatchHexagon to be functionally invisible by replacing it with a 1px by 1px invisible image.</p><h2 id="unit-images" tabindex="-1">Unit images <a class="header-anchor" href="#unit-images" aria-label="Permalink to &quot;Unit images&quot;">​</a></h2><p>Unit images can be changed according to civ-specific styles (if a mod specifies a &quot;style&quot; variable for each civilization) and according to the owning civ&#39;s current era. Unciv attempts to load the unit images in the following order (where unitName is the unit name given in Units.json, styleName is optionally specified in Nations.json, and eraName is the era name given in Eras.json (including &quot; era&quot;)).</p><ol><li>unitName-styleName-eraName (example: &quot;Archer-customStyle1-Classical era.png&quot;)</li><li>unitName-eraName (example: &quot;Archer-Classical era.png&quot;)</li><li>unitName-styleName (example: &quot;Archer-customStyle1.png&quot;)</li><li>unitName (example: &quot;Archer.png&quot;)</li></ol><p>Era-specific sprites do not need to be specified for each era, only on eras where the sprites change. If a modder wants a Great General unit to change sprites starting in the Modern era, they only need to create a &quot;Great General-Modern era.png&quot; image. The Great General unit would use the default &quot;Great General.png&quot; sprite for all eras up to the Modern era then the Modern era sprite for the Modern era and all eras after unless there is a later era sprite for this unit.</p><h3 id="nation-coloured-units" tabindex="-1">Nation-coloured units <a class="header-anchor" href="#nation-coloured-units" aria-label="Permalink to &quot;Nation-coloured units&quot;">​</a></h3><p>Unciv can colour units according to the civilization that owns them. <a href="https://github.com/yairm210/Unciv/pull/3231" target="_blank" rel="noreferrer">[PR3231]</a></p><p>This is used by providing multiple images per unit, each representing a coloured layer. The image suffixed with &quot;-1&quot; will be tinted to the civilization&#39;s inner colour, and the image suffixed with &quot;-2&quot; will be tinted to the civilization&#39;s outer colour. For example:</p><table tabindex="0"><thead><tr><th>Image</th><th>Description</th><th>Colour</th></tr></thead><tbody><tr><td>Archer.png</td><td>Base image</td><td>Untinted</td></tr><tr><td>Archer-1.png</td><td>Colour layer</td><td>Nation inner colour</td></tr><tr><td>Archer-2.png</td><td>Colour layer</td><td>Nation outer colour</td></tr></tbody></table><p>The <a href="https://github.com/AdityaMH/Civ-Army-Color-Style-Sheet/tree/main/Images/TileSets/FantasyHex/Units" target="_blank" rel="noreferrer">Civ Army Color Style Sheet</a> mod by @AdityaMH and the <a href="https://github.com/ravignir/5Hex-Tileset/tree/master/Images/TileSets/5Hex/Units" target="_blank" rel="noreferrer">5Hex Tileset</a> by @ravignir are very good practical examples of how this can be used.</p><h2 id="attack-animations" tabindex="-1">Attack animations <a class="header-anchor" href="#attack-animations" aria-label="Permalink to &quot;Attack animations&quot;">​</a></h2><p>These are small animations that play on units when they receive damage.</p><p>They can be for unit types (Archery, Seige, Cavalry) or for specific unit names</p><p>The files should be in the format of <code>&lt;unit type/unit name&gt;-attack-&lt;frame number&gt;</code>. For example, a 3 frame animation for Sword units would have the files <code>Sword-attack-1.png</code>, <code>Sword-attack-3.png</code>, <code>Sword-attack-3.png</code></p><h2 id="edge-images" tabindex="-1">Edge images <a class="header-anchor" href="#edge-images" aria-label="Permalink to &quot;Edge images&quot;">​</a></h2><p>You can add additional images that will be drawn only when a tile is adjacent to another tile in a specific direction.</p><p>The images should be placed in the <code>Images/Tilesets/&lt;tileset name&gt;/Edges</code> folder, rather than in <code>/Tiles</code>.</p><p>The name of the tile should be <code>&lt;tile name&gt;-&lt;origin tile filter&gt;-&lt;destination tile filter&gt;-&lt;neighbor direction&gt;.png</code>, where direction of one of:</p><ul><li>Bottom</li><li>BottomLeft</li><li>BottomRight</li><li>Top</li><li>TopLeft</li><li>TopRight</li></ul><p>And where the tile filter is one of:</p><ul><li>Terrain name</li><li>Feature name</li><li>Terrain type (Land/Water)</li></ul><p>For example: <code>Cliff-Hills-Coast-Top.png</code> indicates that this image will be drawn ON &quot;Hills&quot; tiles, WHEN &quot;Coast&quot; tiles are TOP of this tile.</p><p>The initial name has no bearing on the image used, it is just a way to group images together.</p>`,67)])])}const k=a(l,[["render",n]]);export{g as __pageData,k as default};
